package org.codenova.start.controller;

import lombok.Getter;
import org.codenova.start.model.Pokemon;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;

import java.util.List;

@Controller
@RequestMapping("/thymeleaf")
public class ThymeleafController {

    @GetMapping("/example/01")
    public String example01Handle(Model model) {

        String[] keyword = new String[]{
                "도전","기회","성장","행운","인내","집중","열정","자신감","전환"
        };

        model.addAttribute("keyword",
                keyword[(int)(Math.random() * keyword.length)]
        );
        model.addAttribute("number", (int) (Math.random() * 10) + 1);

        model.addAttribute("message", "<script>alert('??');</script>");
        return "thymeleaf/example/01";
    }

    @GetMapping("example/02")
    public String example02Handle(Model model){
        Pokemon pokemon = Pokemon.builder().name("이상해씨").type("풀").id(1)
                .imageUrl("https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNDA0MzBfMjA0%2FMDAxNzE0NDMzNDU0MDYw.JVWA4hVnqeY7Bn_FWG_BfDZ1FKg3rVjVqn7tY4n9C70g.4c0kKmpze46L3xaYTI3CkMsspEAFI9AAfEnAguEtWo4g.PNG%2F%25C0%25CC%25BB%25F3%25C7%25D8%25BE%25BE.png&type=a340")
                .unique(true)
                .build();

        model.addAttribute("pokemon",pokemon);
        model.addAttribute("role","admin");

        return "thymeleaf/example/02";
    }
    @GetMapping("example/03")
    public String example03Handle(Model model){
        List<String> names = List.of("이상해씨","파이리","꼬부기","피카츄");
        // role 에 설정할 수 있는 값은 admin, guest 3가지가 있다고 가정
        model.addAttribute("names",names);

        return "thymeleaf/example/03";
    }

    @GetMapping("example/04")
    public String example04Handle(Model model){

        List<Pokemon> pokemons = List.of(
        Pokemon.builder().name("피카츄").imageUrl("data:image/png;base64,").type("전기").build(),
        Pokemon.builder().name("파이리").imageUrl("data:image/jpeg;base64,").type("불").build(),
        Pokemon.builder().name("꼬부기").imageUrl("data:image/jpeg;base64,").type("물").build(),
        Pokemon.builder().name("이상해씨").imageUrl("data:image/jpeg;base64,").type("풀").build()
        );
        model.addAttribute("pokemons", pokemons);
        return "thymeleaf/example/04";
    }
}

